refsection.programlisting:
// From the builder_help.sce script of a toolbox, in its help directory:
// the images of all the languages are generated
tbx_build_help("Toolbox Example", get_absolute_file_path("builder_help.sce"))

// Historical usage, from each help/la_LA/build_help.sce script: the first
// call generates the images of all the languages, the next ones do nothing
tbx_build_help("Toolbox Example", get_absolute_file_path("build_help.sce"))
